<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { LoaderCircle, Pencil, Plus, Shield, Trash2, X } from "lucide-vue-next";
import ConfirmModal from "@/components/operations/ConfirmModal.vue";
import DataPanel from "@/components/operations/DataPanel.vue";
import OpsModal from "@/components/operations/OpsModal.vue";
import { operationsRepository } from "@/data/repositories/operationsRepository";
import type { UiAccessRecord } from "@/data/models/operations";

const roles = ref<UiAccessRecord[]>([]); const permissions = ref<UiAccessRecord[]>([]); const loading = ref(false); const saving = ref(false); const deleting = ref(false); const showForm = ref(false); const error = ref("");
const editingId = ref<number | null>(null); const deleteTarget = ref<UiAccessRecord | null>(null); const defaults = { name: "", slug: "", scope: "system", group: "", is_system: false, permission_ids: [] as number[] }; const form = reactive({ ...defaults });
async function load() { loading.value = true; error.value = ""; try { const [rolePage, permissionPage] = await Promise.all([operationsRepository.roles({ per_page: 100 }), operationsRepository.permissions({ per_page: 100 })]); roles.value = rolePage.items; permissions.value = permissionPage.items; } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to load access control."; } finally { loading.value = false; } }
function openCreate() { editingId.value = null; Object.assign(form, { ...defaults, permission_ids: [] }); showForm.value = true; }
function openEdit(item: UiAccessRecord) { editingId.value = item.id; Object.assign(form, { name: item.name, slug: item.slug, scope: item.scope || "system", group: item.group || "", is_system: item.system, permission_ids: permissions.value.filter((permission) => item.permissions.includes(permission.slug)).map((permission) => permission.id) }); showForm.value = true; }
async function save() { saving.value = true; error.value = ""; const payload = { name: form.name, slug: form.slug, scope: form.scope, is_system: form.is_system, permission_ids: form.permission_ids }; try { if (editingId.value) await operationsRepository.update("roles", editingId.value, payload); else await operationsRepository.create("roles", payload); showForm.value = false; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to save role."; } finally { saving.value = false; } }
async function confirmRemove() { if (!deleteTarget.value) return; deleting.value = true; try { await operationsRepository.remove("roles", deleteTarget.value.id); deleteTarget.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "Unable to delete role."; } finally { deleting.value = false; } }
onMounted(load);
</script>

<template><div class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[12px] font-semibold uppercase tracking-[0.12em] text-violet">Authorisation</p><h2 class="mt-1 text-[26px] font-bold tracking-[-0.035em]">Access control</h2><p class="mt-1 text-[13px] text-ink3">Define system and institute roles with granular permissions.</p></div><button class="ops-button-primary flex items-center gap-2 transition hover:-translate-y-0.5 hover:shadow-md" @click="openCreate"><Plus :size="15" /> Add role</button></div><p v-if="error" class="rounded-xl bg-pink-light px-4 py-3 text-[13px] text-pink">{{ error }}</p><DataPanel title="Role directory" :loading="loading" :empty="!roles.length"><div class="grid gap-4 p-5 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in roles" :key="item.id" class="group rounded-2xl border border-border p-4 transition hover:-translate-y-0.5 hover:shadow-md"><div class="flex items-start justify-between"><div class="grid h-9 w-9 place-items-center rounded-xl bg-violet-light text-violet"><Shield :size="17" /></div><div class="flex gap-1"><button class="ops-icon-button" title="Edit" @click="openEdit(item)"><Pencil :size="14" /></button><button class="ops-icon-button hover:bg-pink-light hover:text-pink" title="Delete" @click="deleteTarget = item"><Trash2 :size="14" /></button></div></div><h3 class="mt-4 text-[14px] font-bold">{{ item.name }}</h3><p class="mt-1 font-mono text-[11px] text-ink3">{{ item.slug }}</p><p class="mt-3 text-[11px] capitalize text-ink2">{{ item.scope || item.group || 'General' }}</p><p class="mt-2 text-[10px] text-ink4">{{ item.permissions.length }} permissions</p></article></div></DataPanel>
  <OpsModal :open="showForm" max-width="max-w-lg" :close-on-backdrop="!saving" @close="showForm = false"><form class="rounded-2xl border border-border bg-bg-card p-5 shadow-2xl" @submit.prevent="save"><div class="mb-5 flex justify-between"><div><h3 class="text-[17px] font-bold">{{ editingId ? 'Edit' : 'New' }} role</h3><p class="mt-1 text-[12px] text-ink3">Use stable slugs because API authorization refers to them.</p></div><button type="button" :disabled="saving" @click="showForm = false"><X :size="18" /></button></div><div class="space-y-3"><label class="text-[11px] font-semibold">Name<input v-model="form.name" required class="ops-input" /></label><label class="text-[11px] font-semibold">Slug<input v-model="form.slug" required class="ops-input" placeholder="resource.action" /></label><label class="text-[11px] font-semibold">Scope<select v-model="form.scope" class="ops-input"><option value="system">System</option><option value="institute">Institute</option></select></label><fieldset><legend class="mb-2 text-[11px] font-semibold">Permissions</legend><div class="grid max-h-48 gap-2 overflow-y-auto rounded-xl border border-border p-3 sm:grid-cols-2"><label v-for="permission in permissions" :key="permission.id" class="flex items-center gap-2 rounded-lg p-1 text-[11px] text-ink2 transition hover:bg-bg-soft"><input v-model="form.permission_ids" type="checkbox" :value="permission.id" /> {{ permission.slug }}</label></div></fieldset></div><div class="mt-5 flex justify-end gap-2"><button type="button" :disabled="saving" class="ops-button-secondary" @click="showForm = false">Cancel</button><button class="ops-button-primary inline-flex min-w-28 items-center justify-center gap-2" :disabled="saving"><LoaderCircle v-if="saving" :size="14" class="animate-spin" />{{ saving ? 'Saving…' : editingId ? 'Update' : 'Create' }}</button></div></form></OpsModal>
  <ConfirmModal :open="Boolean(deleteTarget)" :title="`Delete role?`" :message="`Remove ${deleteTarget?.name || 'this access record'}? Existing assignments may prevent deletion.`" confirm-label="Delete record" :busy="deleting" @close="deleteTarget = null" @confirm="confirmRemove" />
</div></template>
